import React, { useState } from "react";
import Navbarwidgets from "./Navbarwidgets";

function Header() {

    const [selected, setSelected] = useState();

    const imagePath = process.env.PUBLIC_URL + "/Assets/Images/";

    const navbarwidgets = [
        { icon: 'Overview', src: imagePath + 'home.svg' },
        { icon: 'Patients', src: imagePath + 'patient.svg' },
        { icon: 'Schedule', src: imagePath + 'calendar.svg' },
        { icon: 'Message', src: imagePath + 'chat.svg' },
        { icon: 'Transactions', src: imagePath + 'card.svg' }
    ];

    return <div className="header">

        <img className="logo" src={imagePath + "techcare.svg"} alt="TechCare" />

        <div className="widgets-navbar">
            <nav className="navbar">
                {navbarwidgets.map((widget, index) =>
                    <Navbarwidgets
                        key={index}
                        name={widget.icon}
                        link={widget.src}
                        selected={selected === index}
                        onClick={() => setSelected(index)}
                    />
                )}
            </nav>
        </div>

        <div className="doctor-profile">
            <img className="doctor-img" src={imagePath + "doctor.png"} alt="doctor_profile" />

            <div>
                <p id="doc-profile-para1">Dr. Jose Simmons</p>
                <p id="doc-profile-para2">General Practitioner</p>
            </div>

            <div className="divider"></div>

            <img className="profile-icon" src={imagePath + "settings.svg"} alt="settings" />
            <img className="profile-icon" src={imagePath + "more-option.svg"} alt="more options" />

        </div>

    </div>;
}

export default Header;